  "about.founder.p2": "میں کسے وڈی ٹیک کمپنی توں نہیں آئی، تے میں کسے کارپوریٹ دفتر وچ نہیں بیٹھدی۔ میں اک چھوٹی پرچون دکاندار آں، بالکل تواڈے وانگ۔ میں پنج ای کامرس دکاناں چلاندی آں، جیہڑیاں کتاباں تے کتاب پریمیاں لئی ہتھ نال بنیاں شیواں وچ ماہر نیں۔\nبہت سارے آزاد پرچون ویچن والیاں وانگ، میں اک ٹوٹن والے موڑ تے پہنچ گئی سی جدوں میں کئی تھاواں دی انوینٹری سنبھالن، پبلشراں دے ISBN نوں اپنے ہتھ نال بنے SKU دے نال نال ٹریک کرن، تے اناڑی سپریڈشیٹ نال سپلائر آرڈر سنبھالن دی کوشش کر رہی سی۔ جدوں میں مدد لئی کوئی ایپ لبھی، تے میں چھ وکھ وکھ آپشن آزمائے۔ ہر اک یا تے پورا ادھورا سی، یا ناقابل یقین حد تک الجھن والا سی، یا لٹیرا سی — بنیادی اوزاراں لئی مہینے دے سینکڑوں ڈالر وصولدے سن۔",
