  "settings.pastDue.body": "توہاڈی آخری ادائیگی مکمل نہیں ہوئی۔ ناکام ادائیگی توں 14 دن تک توہانوں مکمل استعمال حاصل رہندا اے جد تک تسیں اسنوں درست کرو۔ اگر درست نہ ہووے تے رکنیت منسوخ ہو جاوے گی، ورک اسپیس 15 دن لئی صرف دیکھن دے قابل رہے گی، تے پھر اکاؤنٹ تے اس دی ساری معلومات حذف ہو جاوے گی۔ حذف توں پہلاں کسی وی ویلے ادائیگی کرن نال سب کچھ واپس آ جاندا اے۔ اگر توہانوں یقین نہ ہووے کہ کی کرنا اے تے سپورٹ نال theluminousbookshop@outlook.com اُتے رابطہ کرو۔",
