  "pricing.rollbackHint": "عام قیمت رکھی جاندی ہے تے سیل چلن تک رول بیک قیمت دے نال دکھائی جاندی ہے۔ جدوں ختم ہون دی تاریخ لنگھ جاوے، تے قیمت اپنے آپ عام تے واپس آ جاندی ہے۔",
