  "training.lessons.owner-shipping-labels.step1": "پرنٹ سینٹر وچ دوواں پلاناں وچ شپنگ لیبل سٹائل ہے: گاہک دا آرڈر چنو تے خریدار دے نام تے پتے تے بھیجن والے وجوں تہاڈے کاروبار والا 4×6 لیبل چھاپو۔",
  "training.lessons.owner-shipping-labels.step2": "ایہ لیبل ہر گاہک دستاویز وانگ وائٹ لیبل ہے: ایس تے صرف تہاڈے کاروبار دا نام ہوندا ہے — ایس ایپ دا نام کدے نہیں — تاں جو تہاڈی دکان توں آیا پارسل تہاڈی ای دکان توں آیا لگے۔",
  "training.lessons.owner-shipping-labels.step3": "گاہک دا پتہ اوہناں دے آخری آرڈر توں بعد 90 دناں تک اوہناں دے آرڈراں نال رکھیا جاندا اے، تے لیبل جدوں آرڈر دا محفوظ پتہ ہووے تے اوس توں شروع ہوندا اے؛ اک وار دے لیبل لئی چھپائی ویلے لکھیا پتہ واپس محفوظ نئیں کیتا جاندا۔ ناں فیر وی آرڈر توں بھریا جاندا اے تاں جو لیبل کاغذات نال ملے۔",
  "training.lessons.owner-shipping-labels.step4": "ایہ لیبل ہر لیبل وانگ اوہی چار کنکشنز راہیں چھپدا ہے — بلوٹوتھ، وائی فائی، ایتھرنیٹ تے USB — تے 4×6 تھرمل پرنٹر ایس دا معیاری سائز ہے۔",
  "training.lessons.owner-shipping-labels.step5": "اس دی بجائے ڈاک خرچ کیریئر توں خریدیا؟ اسے حصے وچ تسیں کیریئر دی لیبل فائل — PDF، PNG یا JPG — اپ لوڈ کر سکدے او اتے ایہ آرڈر اتے ہمیشہ محفوظ رہے گی: تہاڈا ریکارڈ، جے کجھ ہو جائے تے ہتھ وچ۔ ایہ اپنے اصل 4×6 سائز وچ چھپدی اے۔ ایپ کدی ڈاک خرچ نہیں ویچدی، اس لئی کیریئر دی قیمت ای اکو قیمت اے — اتے ہمیشہ درست قیمت۔",
  "training.lessons.owner-shipping-labels.title": "گاہک آرڈراں لئی شپنگ لیبل",
  "training.lessons.print-shipping-label.step1": "جدوں آرڈر بھیجن لئی تیار ہووے، پرنٹ سینٹر کھولو، شپنگ لیبل سٹائل چنو تے فیر گاہک دا آرڈر چنو۔ خریدار دا نام آرڈر توں بھریا جاندا ہے۔",
  "training.lessons.print-shipping-label.step2": "اوہ پتہ جانچو جتھے پارسل جا رہیا اے۔ جدوں آرڈر وچ گاہک دا پتہ ہووے — اوہناں دے آخری آرڈر توں بعد 90 دناں تک رکھیا گیا — تے ایہ تواڈے لئی بھریا جاندا اے؛ چھپائی ویلے تسی جو پتہ لکھدے او اوہ واپس محفوظ نئیں ہوندا، ایس لئی چھاپن توں پہلاں پوسٹ کوڈ تے آخری لائن دھیان نال جانچو۔",
  "training.lessons.print-shipping-label.step3": "تہاڈے کاروبار دا نام بھیجن والے وجوں اتے چھپدا ہے۔ جے تہاڈا پتہ وی لیبل تے چاہیدا ہے، تے اوسنوں بھیجن والے دے پتے والے خانے وچ لکھو؛ جے نہیں دکھانا تے خالی چھڈو۔",
  "training.lessons.print-shipping-label.step4": "4×6 لیبل تے چھاپو — تھرمل لیبل پرنٹر عام چون ہے — یا براؤزر دے پرنٹ بٹن نال کسے وی پرنٹر تے۔ لیبل نوں پارسل تے ہموار چپکاؤ، جتھے ایہ کنارے تے نہ مڑے۔",
  "training.lessons.print-shipping-label.step5": "جے ڈاک خرچ کیریئر توں خریدیا گیا سی، تے اس دی بجائے اوہناں دی لیبل فائل آرڈر اتے محفوظ کرو: تہاڈے کیریئر دا لیبل حصے وچ کیریئر ولوں دتی PDF، PNG یا JPG اپ لوڈ کرو۔ ایہ تہاڈے ریکارڈ وجوں آرڈر اتے رہندی اے اتے اپنے اصل 4×6 سائز وچ چھپدی اے — اتے جدوں تسیں اس نوں ورتنا چاہو تے ایپ دا اپنا پتہ لیبل ہمیشہ اوتھے ہوندا اے۔",
  "training.lessons.print-shipping-label.title": "شپنگ لیبل چھاپو",
