  "staffWelcome.editor.title": "نویں عملے لئی خوش آمدیدی پیغام",
  "staffWelcome.editor.description": "اوہ الفاظ جو اک نیا شخص اک وار، اپنے پہلے سائن ان تے، ہر چیز توں پہلاں پڑھدا ہے۔ انہاں نوں اپنے الفاظ وچ لکھو تاکہ ایہ تواڈی دکان جیہا محسوس ہووے۔",
  "staffWelcome.editor.permanentNote": "ایہ پہلی سطر خود ایپ ہے — ایہ ہمیشہ دکھائی دیندی ہے اتے اس نوں نہ بدلیا جا سکدا ہے نہ ہٹایا جا سکدا ہے۔",
  "staffWelcome.editor.tokens": "{name} اوتھے لکھو جتھے شخص دا پہلا نام آنا چاہیدا ہے، اتے {store} اوتھے جتھے تواڈی دکان دا نام آنا چاہیدا ہے — ایپ ہر شخص لئی انہاں نوں بھر دیندی ہے۔",
  "staffWelcome.editor.emptyNote": "خانہ خالی چھڈ دیو تاکہ ایپ دا معیاری خوش آمدید ورتیا جاوے (جو خانے وچ ہلکا سا دکھائی دیندا ہے)۔ نیا شخص کدی خالی صفحہ نہیں دیکھدا۔",
  "staffWelcome.editor.save": "خوش آمدیدی پیغام محفوظ کرو",
  "staffWelcome.editor.saved": "خوش آمدیدی پیغام محفوظ ہو گیا۔",
  "training.lessons.staff-shift-windows.title": "تواڈا سائن ان تواڈی شفٹ دے پچھے چلدا ہے",
  "training.lessons.staff-shift-windows.step1": "تسی اپنی مقررہ شفٹ شروع ہون توں تقریباً 10 منٹ پہلاں توں سائن ان کر سکدے ہو۔ اس توں پہلاں ایپ بند رہندی ہے — سائن ان صفحہ توانوں بتائے گا کہ تواڈی اگلی شفٹ کدو شروع ہندی ہے۔",
  "training.lessons.staff-shift-windows.step2": "جیسے ہی تسی کلاک آؤٹ کردے ہو، تواڈے کول اپنا صفحہ چیک کرن لئی 10 منٹ ہندے نیں، کیونکہ تواڈی اگلی مقررہ تاریخ تک توانوں لاگ آؤٹ کر دتا جاوے گا۔",
  "training.lessons.staff-shift-windows.step3": "جے تسی انہاں 10 منٹاں دے اندر دوبارہ کلاک ان کر لو تے لاگ آؤٹ منسوخ ہو جاندا ہے اتے تسی سائن ان رہندے ہو۔",
  "training.lessons.staff-shift-windows.step4": "شیڈول وچ شفٹ نہ ہو تے اس دن سائن ان نہیں ہو سکدا۔ جے تسی سمجھدے ہو کہ توانوں شیڈول وچ ہونا چاہیدا ہے تے اپنے مینیجر یا مالک نوں پوچھو — اوہی شیڈول شائع کردے نیں جو تواڈا دروازہ کھولدا ہے۔",
  "training.lessons.manager-shift-windows.title": "شیڈول شائع کرنا رسائی کھولدا اتے بند کردا ہے",
  "training.lessons.manager-shift-windows.step1": "جو شیڈول تسی اپنی ٹیم لئی شائع کردے ہو اوہ شفٹاں دی فہرست توں ودھ ہے: ایہی ہر شخص دی ایپ تک رسائی کھولدا اتے بند کردا ہے۔ ٹیم دا رکن اس شفٹ توں تقریباً 10 منٹ پہلاں سائن ان کر سکدا ہے جو تسی اس لئی شائع کیتی — اس توں پہلاں نہیں۔",
  "training.lessons.manager-shift-windows.step2": "جدوں اوہ کلاک آؤٹ کردا ہے تے اس کول اپنے ویلے چیک کرن لئی تقریباً 10 منٹ ہندے نیں، پھر ایپ اس دی اگلی مقررہ شفٹ تک اس نوں لاگ آؤٹ کر دیندی ہے۔ اس دن کوئی شائع شدہ شفٹ نہ ہو تے اوہ اس دن سائن ان نہیں کر سکدا۔",
  "training.lessons.manager-shift-windows.step3": "شفٹاں احتیاط نال شائع کرو: غائب یا غلط شفٹ کسے شخص نوں صرف شیڈول توں نہیں، ایپ توں وی باہر بند کر دیندی ہے۔ جے کوئی کہے کہ اوہ اندر نہیں آ سکدا تے پہلاں اس دا شیڈول چیک کرو۔",
  "training.lessons.manager-shift-windows.step4": "تواڈی اپنی رسائی وی اسی طرح کم کردی ہے، اک درجہ اتے: جو شیڈول مالک تواڈے لئی شائع کردا ہے اوہ تواڈی ونڈو تواڈی شفٹ توں تقریباً 10 منٹ پہلاں کھولدا ہے، اتے تواڈے کلاک آؤٹ دے تقریباً 10 منٹ بعد تواڈا سیشن بند ہو جاندا ہے۔",
  "training.lessons.owner-shift-windows.title": "شفٹ ونڈوز: شیڈول رسائی کھولدا اتے بند کردا ہے",
  "training.lessons.owner-shift-windows.step1": "رسائی اس شیڈول دے پچھے چلدی ہے جو تسی شائع کردے ہو۔ عملے دا رکن یا مینیجر اپنی مقررہ شفٹ توں تقریباً 10 منٹ پہلاں سائن ان کر سکدا ہے — اس توں پہلاں نہیں۔ شفٹ توں باہر ایپ انہاں لئی بند رہندی ہے، تاکہ دکان دی معلومات ڈیوٹی تے موجود لوکاں کول رہن۔",
  "training.lessons.owner-shift-windows.step2": "جدوں اوہ کلاک آؤٹ کردے نیں تے انہاں کول اپنے ویلے چیک کرن لئی تقریباً 10 منٹ ہندے نیں، پھر ایپ خود ہی انہاں دی اگلی مقررہ شفٹ تک انہاں نوں لاگ آؤٹ کر دیندی ہے۔ انہاں 10 منٹاں دے اندر دوبارہ کلاک ان کرنا لاگ آؤٹ منسوخ کر دیندا ہے۔",
  "training.lessons.owner-shift-windows.step3": "اس دن کوئی شائع شدہ شفٹ نہ ہو تے اس دن کوئی ونڈو نہیں: جو شخص شیڈول وچ نہیں اوہ سائن ان نہیں کر سکدا۔ شیڈول ورک فورس وچ شائع کرو، اس دا دروازہ اسی دے نال کھل جاوے گا۔",
  "training.lessons.owner-shift-windows.step4": "تسی واحد استثنا ہو: مالک نوں کوئی شیڈول نہیں کردا، اس لئی تواڈے سائن ان دی کدی کوئی ونڈو نہیں ہندی۔ مینیجر اس شیڈول توں محدود ہندا ہے جو تسی اس لئی شائع کردے ہو، اسی طرح جیسے عملہ انہاں لئی شائع شدہ شیڈول توں محدود ہندا ہے۔",
  "settings.install.ownerNote": "جے تواڈا ایپ اسٹور کدی توانوں ایپ ورتن توں روکے، تے ایہ لنک توانوں ایپ براہ راست اسی ویب سائٹ توں دیندا ہے — اسٹور دی لوڑ نہیں۔",
  "layout.signOutLink": "لاگ آؤٹ کرو",
