  "plansLib.includes.shiftWindows": "شفٹ نال جڑی رسائی — ایپ مقررہ شفٹ توں 10 منٹ پہلاں کھلدی ہے اتے کلاک آؤٹ توں بعد لاگ آؤٹ کردی ہے",
  "plansLib.includes.ownerOnlyBilling": "آزمائش اتے بلنگ دیاں اطلاعات صرف مالک لئی — عملے نوں کدی نہیں دکھائیاں جاندیاں",
  "plansLib.includes.settingsGrants": "مالک دی دتی ہوئی ترتیبات تک رسائی، بندہ بہ بندہ",
  "plansLib.includes.appDownload": "ایپ نوں ترتیبات توں ڈاؤن لوڈ کرو — یا جے گم ہو جاوے تے اس نوں واپس حاصل کرو",
  "plansLib.includes.staffWelcome": "ہر نویں ملازم لئی ذاتی خوش آمدید صفحہ",
  "plansLib.includes.inviteLink": "اک ٹیپ سائن اپ لنک نال عملے دیاں دعوتاں",
  "subscribe.memberNote": "تسی اس ورک سپیس دے ممبر دے طور تے سائن ان ہو۔ ایہ صفحہ کاروبار دے مالک دا ہے — جے توانوں ایتھے کجھ چاہیدا ہے تے اوہناں نوں پوچھو۔",
  "subscribe.memberOpenApp": "ایپ کھولو",
  "apiErrors.planLimitNeutral": "ایہ ہنے شامل نہیں کیتا جا سکدا — کاروبار دے مالک نوں پوچھو۔",
  "training.lessons.owner-confidentiality.title": "توہاڈی معلومات خفیہ رہندی ہے",
  "training.lessons.owner-confidentiality.step1": "Luminous StockHaven توہاڈی معلومات نوں توہاڈے عملے توں خفیہ رکھدا ہے۔ توہاڈیاں ادائیگیاں، توہاڈی آزمائش، توہاڈی رکنیت اتے توہاڈی بلنگ دی حالت — اتے توہاڈی ذاتی معلومات بارے کچھ وی — صرف توہاڈی ہے: عملہ اتے منیجر اوہناں نوں کدی نہیں دیکھدے، ایپ وچ کتھے وی نہیں۔",
  "training.lessons.owner-confidentiality.step2": "اس وچ خاموش تھاں واں وی شامل ہن: اوہناں دے صفحات اتے آزمائش دی الٹی گنتی نہیں، اوہناں دیاں ترتیبات وچ منصوبہ یا بلنگ دا کوئی حصہ نہیں، ادائیگی دی کوئی وارننگ نہیں۔ اوہناں دیاں ترتیبات ذاتی ہن — اوہناں دا اپنا اکاؤنٹ، سیکیورٹی، ظاہری شکل اتے بولی — علاوہ صرف اوہ اضافی حصے جو تسی اوہناں لئی منتخب کرو۔ بلنگ کدی وی نشانات وچوں نہیں ہے۔",
  "training.lessons.owner-confidentiality.step3": "جے اکاؤنٹ کدی بلنگ دی وجہ توں رک جاوے، تے توہاڈے عملے نوں کدی نہیں دسیا جاوے گا کہ کیوں۔ اوہ صرف اک سادہ، غیر جانبدار روک دیکھدے ہن — تبدیلیاں ہنے بند ہن — تاکہ تسی اپنی ٹیم نوں اپنے لفظاں وچ سمجھا سکو۔",
  "training.lessons.owner-confidentiality.step4": "اتے جے تسی کدی کچھ ایسا دیکھو جو توہاڈے عملے نوں دکھایا جا رہیا ہووے اتے نہیں دکھایا جانا چاہیدا — کوئی وی لیک — ترتیبات کھولو اتے مسئلہ رپورٹ کرو تے ٹیپ کر کے سانوں دسو، تاکہ اسی اس نوں جلد توں جلد ٹھیک کر سکئے۔",
