  "apiErrors.notFound.voiceNoteFound": "وائس نوٹ نہیں ملیا۔",
  "apiErrors.invalidValue.sendVoiceRecording": "ودھ توں ودھ چند منٹ دی وائس ریکارڈنگ گھلو۔",
