  "training.lessons.messages-private.step5": "تسیں وائس نوٹ وی گھل سکدے او: پیغام والے ڈبے کول مائیکروفون نوں چھوؤ، بولو، تے روکو نوں چھوؤ۔ پہلاں اینوں سنو — فیر گھلو، یا مٹا کے دوبارہ ریکارڈ کرو۔ جدوں کوئی تہانوں گھلے تے اوہدی اصل آواز سنن لئی چلاؤ نوں چھوؤ۔",
  "training.lessons.owner-messages-oversight.step5": "پڑھن دے نشان: جدوں ٹیم دا کوئی رکن تہاڈا گھلیا پیغام پڑھدا اے، تسیں ویکھدے او کہ اوہ پڑھیا ہویا نشان لگیا اے۔ عملہ تے مینیجر اک دوجے دے پڑھن دے نشان ایسے طراں ویکھدے نیں، دوویں پاسے۔",
  "training.lessons.owner-messages-oversight.step6": "تہاڈا اپنا پڑھنا نظر نہیں آندا۔ جدوں تسیں عملے دے کسے رکن دا گھلیا پیغام پڑھدے او، اوہ کدی پڑھن دا نشان نہیں ویکھدا — تے تہانوں اپنی ٹیم نوں ایہ دسن دی لوڑ نہیں کہ اوہناں دیاں گلاں ایپ وچ محفوظ ہوندیاں نیں تے تسیں، مالک، اوہناں نوں پڑھ سکدے او۔ ایہ نگرانی تہاڈی دکان دی دیکھ بھال دا حصہ اے۔",
  "training.lessons.owner-messages-oversight.step7": "عملے دے رکناں وچکار منفی پیغاماں بارے تسیں کی کردے او، ایہ تہاڈے اتے اے۔ اینوں لنگھ جाण دیو، کسے نال خاموشی نال گل کرو، یا کارروائی کرو — چناؤ تہاڈا اے، تے تہانوں کدی ایہ دسن دی لوڑ نہیں کہ تسیں ایہ کتھے ویکھیا۔",
