  "training.lessons.owner-store-policies.title": "تہاڈے سٹور دیاں پالیسیاں تے شرطاں",
  "training.lessons.owner-store-policies.step1": "سیٹنگاں کھولو تے سٹور پالیسیاں تے شرطاں والا کارڈ لبھو۔ اس وچ دو دستاویزاں نیں: تہاڈے سٹور دیاں پالیسیاں — تہاڈے سٹور لئی گھر دے اصول — تے تہاڈیاں شرطاں تے ضابطے۔",
  "training.lessons.owner-store-policies.step2": "ہر دستاویز اوتھے ہی لکھی جا سکدی ہے، یا فائل وجوں اپ لوڈ کیتی جا سکدی ہے (PDF، لکھت، Word یا OpenDocument، 25 MB تک)۔ اک یا دوجی: لکھت بچاؤن نال فائل بدل جاندی ہے، تے فائل اپ لوڈ کرن نال لکھت بدل جاندی ہے۔ دستاویز ہٹاؤن نال اوہ صاف ہو جاندی ہے۔",
  "training.lessons.owner-store-policies.step3": "تہاڈی ٹیم دوویں دستاویزاں اک وار ویکھدی ہے، اوہناں دی پہلی شروعات ویلے اوہناں دے سواگت صفے تے، تے اوہناں نوں کسے وی ویلے اپنیاں سیٹنگاں وچ پڑھ سکدی ہے۔ تہاڈی ٹیم لئی اوہ صرف پڑھن لئی نیں — اوہناں نوں صرف تسی ہی لکھ یا بدل سکدے ہو۔",
  "training.lessons.owner-store-policies.step4": "ہر کاروبار اپنے دستاویز اپنے کول رکھدا ہے: تسی ایتھے جو لکھدے ہو اوہ صرف اس سٹور دا ہے تے کدے کسے ہور کاروبار وچ نہیں دسدا۔ Luminous StockHaven دیاں اپنیاں شرطاں تے پالیسیاں سیٹنگاں وچ تہاڈے دستاویزاں دے نال رہندیاں نیں، تے اوہناں نوں وی ہر کوئی پڑھ سکدا ہے۔",
  "training.lessons.welcome-basics.step5": "تہاڈے سٹور دیاں پالیسیاں تے شرطاں تہاڈے سواگت صفے تے اک وار وکھائیاں جاندیاں نیں، تے اوہ سیٹنگاں وچ رہندیاں نیں، جتھے تسی اوہناں نوں کسے وی ویلے پڑھ سکدے ہو۔",
