  "training.lessons.your-profile-photo.step1": "تہاڈی فوٹو ایپ دے اتے تہاڈے ناں دے نال، عملے دے صفحے اتے، تے تہاڈے سنیہیاں دے نال نظر آندی اے — مالک دے اینوں منظور کرن توں بعد۔ اودوں تک، صرف تہاڈے ناں دے پہلے اکھر نظر آندے نیں۔",
  "training.lessons.your-profile-photo.step2": "ترتیباں کھولو تے اپنی پروفائل فوٹو لبھو۔ اپنی فوٹو چنو تے گھلو۔ ایہ منظوری لئی مالک کول جاندی اے — اڈیک دوران ایہ کدرے وی نظر نہیں آندی۔",
  "training.lessons.your-profile-photo.step3": "جدوں مالک اینوں منظور کردا اے، تہاڈی گھنٹی وجدی اے تے تہاڈی فوٹو نظر آنا شروع ہو جاندی اے۔ جے ایہ منظور نہ ہووے، تے کوئی وکھری فوٹو چنو تے اوہ گھلو۔",
  "training.lessons.your-profile-photo.step4": "اپنی فوٹو بدلنا وی اویں ہی کم کردا اے: نویں فوٹو منظوری دی اڈیک کردی اے، تے نویں فوٹو منظور ہون تک تہاڈی موجودہ فوٹو اویں ہی رہندی اے۔ جے تبدیلی منظور نہ ہووے، تے تہاڈی دوجی فوٹو تہاڈے کول ہی رہندی اے۔",
  "training.lessons.owner-profile-photos.title": "پروفائل فوٹواں تے تہاڈا ناں",
  "training.lessons.owner-profile-photos.step1": "ہر کسے دی فوٹو ایپ دے اتے اوہناں دے ناں دے نال، تہاڈے عملے دے صفحے اتے، تے اوہناں دے سنیہیاں دے نال نظر آندی اے۔ جدوں تک تسیں منظور نہیں کردے، ٹیم ممبر دی فوٹو کدرے وی نظر نہیں آندی — منظوری صرف تہاڈی اے، تے کوئی وی اپنی فوٹو آپ منظور نہیں کر سکدا۔",
  "training.lessons.owner-profile-photos.step2": "جدوں کوئی فوٹو گھلدا اے، تے تہاڈی گھنٹی وجدی اے۔ اینوں ویکھن لئی عملے دا صفحہ کھولو، فیر منظور کرو یا منظور نہ کرو چنو۔ جے تسیں منظور نہیں کردے، تے اوس بندے نوں کوئی ہور فوٹو چنن لئی آکھیا جاندا اے۔",
  "training.lessons.owner-profile-photos.step3": "جے کوئی بندہ اپنی فوٹو بدلدا اے، تے نویں فوٹو اویں ہی تہاڈی منظوری دی اڈیک کردی اے۔ اڈیک دوران اوہناں دی موجودہ فوٹو اویں ہی رہندی اے — تے جے تسیں تبدیلی منظور نہیں کردے تے اوہ اویں ہی رہندی اے۔",
  "training.lessons.owner-profile-photos.step4": "تہاڈی اپنی فوٹو نوں کسے منظوری دی لوڑ نہیں: اینوں ترتیباں وچ، تہاڈی پروفائل فوٹو دے ہیٹھاں سیٹ کرو۔ اوسے کارڈ وچ تہاڈا ناں وی ہوندا اے — جو ناں تسیں اوتھے سیٹ کردے او، اوہ تہاڈی ٹیم جتھے وی ویکھدی اے، ایپ وچ تے سنیہیاں وچ، مالک لفظ دی تھاں لیندا اے۔",
