  "training.lessons.mgr-clock-callin.step1": "مالک مینیجر نوں دو وکھرے نشان دے سکدا ہے۔ کال اِن نال، تسیں سٹاف ممبر لئی کال اِن ونڈو کھول سکدے او، اتے گھڑی بورڈ اتے رہ گئے گھڑی-آؤٹ نال، تسیں ٹیم دا گھڑی بورڈ ویکھ سکدے او اتے سٹاف پیج توں ویلے دیاں اندراجاں ٹھیک کر سکدے او۔ ہر نشان اپنے آپ کم کردا ہے — مینیجر اک توں بغیر دوجا رکھ سکدا ہے۔",
  "training.lessons.mgr-clock-callin.step2": "کال اِن ونڈو کسے بندے نوں اودوں سائن اِن اتے کلاک اِن کرن دیندی ہے جدوں کوئی شفٹ اوہنوں نہ ڈھکدی ہووے۔ اوہنوں سٹاف پیج اُتے، کال اِن اتے چھٹے کلاک آؤٹ کارڈ توں کھولو۔",
  "training.lessons.mgr-clock-callin.step3": "ونڈو اودوں تک کھلی رہندی ہے جدوں تک اوہ بندہ کلاک آؤٹ نہ کرے — فیر سائن آؤٹ توں پہلاں دی عام 10 منٹ دی چھوٹ آؤندی ہے — یا جدوں تک تسیں یا مالک اوہنوں پہلاں بند نہ کرو۔ کجھ وی اوہنوں آپے بند نہیں کردا۔",
  "training.lessons.mgr-clock-callin.step4": "جدوں کوئی کلاک آؤٹ کرنا بھل جاندا ہے، تاں طے شفٹ ختم ہوندیاں ہی اوہدا اندراج سٹاف پیج اتے پے رول وچ نشان زد ہو جاندا ہے، اتے توانوں اتے مالک نوں اطلاع ملدی ہے۔ اندراج ٹھیک ہون تک گندا رہندا ہے۔",
  "training.lessons.mgr-clock-callin.step5": "سٹاف پیج توں اندراج ٹھیک کرو: کلاک اِن، کلاک آؤٹ اتے وقفیاں دے ویلے طے کرو۔ مینیجر صرف سٹاف دیاں اندراجاں ٹھیک کردا ہے — مینیجر دیاں اپنیاں اندراجاں مالک ٹھیک کردا ہے۔",
  "staffLib.perm.staffDocuments": "سٹاف دستاویزات",
  "staffLib.area.documentsAccess": "سٹاف دستاویزات",
  "staff.memberDialog.documentsAccessHint": "صرف مینیجراں لئی — اس ٹک نال، ایہ مینیجر سٹاف ممبراں دیاں دستاویز فائلاں کھول سکدا اے: ہر بندے لئی رکھے کاغذات، جیویں W-4 فارم، نوکری دیاں درخواستاں تے شناختی کارڈ دیاں کاپیاں۔ پہلاں تہاڈی تصدیق منگی جائے گی — ایہناں فائلاں وچ سوشل سیکیورٹی نمبر تے جنم تریخاں ہندیاں نیں۔ ایہ ٹک سٹاف لئی کجھ نئیں کردا۔",
  "staff.documentsWarning.body": "ایہ بندہ تہاڈے سٹاف ممبراں بارے خفیہ معلومات ویکھ سکے گا، جس وچ سوشل سیکیورٹی نمبر تے جنم تریخاں شامل نیں۔",
