  "staff.documents.mineDesc": "اوہ کاغذات جیہڑے تہاڈا مالک تہاڈے لئی فائل وچ رکھدا اے — W-4 فارم، تہاڈی نوکری دی درخواست، ٹیکس فارم، شناختی کارڈ دیاں کاپیاں۔ ایہہ تہاڈی اپنی فائل اے: تساں ایہدے وچ دی کوئی وی چیز کھول، ڈاؤن لوڈ تے چھاپ سکدے او، پر ایتھے کجھ بدلیا نئیں جا سکدا۔",
