  "xstore.help": "ایس کھاتے اُتے سارے لوک، تہاڈے سارے کاروباراں وچ، اکو اِن باکس وچ۔ ایتھے اوہناں وچوں کسے نوں وی سنیہا بھیجو — لکھ کے یا آواز وچ، پہنچن تے پڑھے جان دے نشاناں نال۔ تہاڈے سٹور دے اندر والے سنیہے جیویں نیں، اویویں ای رہن گے۔",
