  "xstore.noPeople": "حالے سنیہا بھیجن لئی کوئی ہور نئیں۔ لوک ایتھے اودوں وکھائی دیندے نیں جدوں اوہ تہاڈے کسے کاروبار وچ شامل ہو کے سائن اِن کر لیندے نیں۔",
  "xstore.deliveredLabel": "پہنچ گیا",
  "apiErrors.planGated.crossStoreMessagesPartBusiness": "سارے سٹوراں وچ سنیہے بزنس پلان دا حصہ نیں۔",
  "apiErrors.invalidValue.personNotPartAccount": "اوہ بندہ ایس کھاتے دا حصہ نئیں۔",
  "training.lessons.owner-xstore-messages.title": "تہاڈے سٹوراں وچ سنیہے، مالکاں لئی",
  "training.lessons.owner-xstore-messages.step1": "سارے سٹوراں وچ سنیہے سنیہیاں توں وکھرا دوجا اِن باکس اے۔ سنیہے اوس سٹور لئی نیں جتھے تسی کھلوتے او؛ ایہ بوہا تہاڈے کھاتے اُتے ہر کسے تک پہنچدا اے، تہاڈے ہر کاروبار وچ — پنج تک۔",
  "training.lessons.owner-xstore-messages.step2": "مینیو توں سارے سٹوراں وچ سنیہے کھولو تے لسٹ وچ کسے نال وی گل بات شروع کرو۔ لسٹ تہاڈے سارے کاروباراں وچ ہر ٹیم ممبر نوں وکھاندی اے جیہڑا سائن اِن کر چکیا اے، اوہناں سٹوراں سنے جتھے اوہ کم کردے نیں۔",
  "training.lessons.owner-xstore-messages.step3": "تصویراں نال چلدیاں نیں: ہر بندہ اپنی منظور شدہ پروفائل تصویر وکھاندا اے، یا جدوں کوئی نہ ہووے تے اپنے ناں دے پہلے حرف۔ ہر سنیہے نال اوہ تریخ تے ویلا ہوندا اے جدوں اوہ بھیجیا گیا سی۔",
  "training.lessons.owner-xstore-messages.step4": "اپنے سنیہیاں دے تھلے تسی ویکھ سکدے او کہ سنیہا پہنچن اُتے پہنچ گیا، تے جدوں دوجا بندہ گل بات کھولدا اے تے پڑھ لیا۔ آواز والے نوٹ ایتھے وی کم کردے نیں، بالکل سنیہیاں وچ وانگوں۔",
  "training.lessons.owner-xstore-messages.step5": "ایتھے دیاں گل باتاں اوہناں دو بندیاں لئی نجی نیں جیہڑے اوہناں وچ نیں۔ تہاڈی سٹور دے اندر سنیہیاں اُتے نگرانی سٹوراں توں پار نئیں پہنچدی۔",
  "training.lessons.mgr-xstore-messages.title": "تہاڈے سٹوراں وچ سنیہے، مینیجراں لئی",
  "training.lessons.mgr-xstore-messages.step1": "سارے سٹوراں وچ سنیہے ایس کھاتے اُتے ہر کسے تک پہنچدے نیں، ہر کاروبار وچ — صرف اوس سٹور تک نئیں جتھے تسی کھلوتے او۔ ایہ مینیو وچ اے، سنیہیاں توں وکھرا۔",
  "training.lessons.mgr-xstore-messages.step2": "لسٹ توں گل بات شروع کرو: ہر ٹیم ممبر جیہڑا سائن اِن کر چکیا اے اوتھے اے، اوہدے ناں دے نال اوہ سٹور جتھے اوہ کم کردا اے۔",
  "training.lessons.mgr-xstore-messages.step3": "لکھ کے بھیجو، یا آواز والا نوٹ ریکارڈ کرو۔ آواز والا نوٹ بھیجن توں پہلاں، تسی اوہنوں سن سکدے او، سُٹ سکدے او، یا بھیج سکدے او — بالکل سنیہیاں وچ وانگوں۔",
  "training.lessons.mgr-xstore-messages.step4": "تہاڈے سنیہے پہنچن اُتے پہنچ گیا وکھاندے نیں تے جدوں دوجا بندہ گل بات کھولدا اے تے پڑھ لیا۔ ہر ناں دے نال والی تصویر اوس بندے دی منظور شدہ پروفائل تصویر اے۔",
  "training.lessons.staff-xstore-messages.title": "تہاڈے سٹوراں وچ سنیہے",
  "training.lessons.staff-xstore-messages.step1": "سارے سٹوراں وچ سنیہے اوہ تھاں اے جتھے تسی ایس کھاتے اُتے کسے نوں وی، مالک دے کسے وی کاروبار وچ، پہنچ سکدے او — دوجے سٹور لئی سوال نوں ہن انتظار نئیں کرنا پویگا۔",
  "training.lessons.staff-xstore-messages.step2": "مینیو توں کھولو، بندہ چنو، تے لکھو۔ جیہڑا بندہ تہانوں چاہیدا اے جے اوہ لسٹ وچ نئیں، تے اوہنے حالے سائن اِن نئیں کیتا — اوہ جیویں ای کردا اے، وکھائی دیندا اے۔",
  "training.lessons.staff-xstore-messages.step3": "تسی ایتھے آواز والے نوٹ وی بھیج سکدے او: ریکارڈ کرو، سن کے ویکھو، فیر بھیجو یا سُٹ دیو۔ ہر سنیہا اوہ تریخ تے ویلا وکھاندا اے جدوں اوہ بھیجیا گیا سی۔",
  "training.lessons.staff-xstore-messages.step4": "جدوں تسی سنیہا بھیجدے او، اوہ پہنچن اُتے پہنچ گیا وکھاندا اے، تے جدوں دوجا بندہ گل بات کھولدا اے تے پڑھ لیا۔ گل بات تہاڈے تے دوجے بندے لئی نجی اے۔",
