  "storefronts.ebayDesc": "اپنے eBay سٹور فرنٹ نوں اک وار منسلک کرو۔ جدوں کوئی آئٹم eBay تے وکدا ہے، تاں اس دی گنتی ایتھے خود بخود گھٹ جاندی ہے، تے فروخت تواڈی نقل و حرکت وچ ریکارڈ ہو جاندی ہے — بالکل اینویں جیویں اس نوں سکین کر کے کڈھیا گیا ہووے۔ فروخت صرف اک ہی سمت وچ آندی ہے: eBay توں ایپ وچ۔",
