  "storefronts.subtitle": "اک سٹور فرنٹ نوں اک وار منسلک کرو، تے اس دی فروخت تواڈے سٹاک نوں خود بخود اپ ڈیٹ کرے گی۔",
  "storefronts.title": "سٹور فرنٹ کنکشنز",
  "training.lessons.owner-ebay-connect.step1": "سٹور فرنٹ کنکشنز کھولو (سیلز گروپ وچ) تے eBay منسلک کرو تے ٹیپ کرو۔ تسیں eBay دے اپنے صفحے تے سائن ان کردے او — ایپ کدی وی تواڈا eBay پاس ورڈ نہیں ویکھدی۔",
  "training.lessons.owner-ebay-connect.step2": "اک eBay سٹور فرنٹ اک کاروبار نال منسلک ہوندا ہے — اوہ کاروبار جس دا سامان اوہ سٹور ویچدا ہے۔ جے تسیں اک توں ودھ کاروبار چلاندے او، تاں ہر سٹور نوں اس دے اپنے کاروبار نال منسلک کرو۔",
  "training.lessons.owner-ebay-connect.step3": "اوہ مقام چنو جتھے تواڈا eBay سٹاک موجود ہے، تاں جو فروخت درست شیلف توں کٹے۔",
  "training.lessons.owner-ebay-connect.step4": "اس دے بعد توں، فروخت خود بخود آندی ہے: جدوں کوئی آئٹم eBay تے وکدا ہے، تاں اس دی گنتی ایتھے گھٹ جاندی ہے تے فروخت eBay آرڈر نمبر نال نقل و حرکت وچ ریکارڈ ہو جاندی ہے۔ کچھ وی واپس نہیں جاندا — ایپ کدی وی تواڈیاں eBay لسٹنگز نوں تبدیل نہیں کردی۔",
  "training.lessons.owner-ebay-connect.step5": "اک فروخت لسٹ تے موجود SKU، UPC یا ISBN نال ملدی ہے — انہاں تیناں وچوں جہڑا وی لسٹ تے ہووے۔ جے کوئی فروخت نہ مل سکے، تاں اوہ سٹور فرنٹ کنکشنز صفحے تے «فروخت جنہاں نوں ملان دی لوڑ ہے» دے تحت انتظار کردی ہے: اس نوں اک وار اس دی پروڈکٹ نال منسلک کرو، تے اوہ فروخت — تے اس ورگی مستقبل دی فروخت — خود بخود ریکارڈ ہو جائے گی۔ «ہن فروخت چیک کرو» کوئی وی حالیہ چیز لے آندا ہے، تے منقطع کرو کنکشن روک دیندا ہے؛ پہلاں توں ریکارڈ شدہ فروخت باقی رہندی ہے۔",
  "training.lessons.owner-ebay-connect.title": "اپنا eBay سٹور منسلک کرو",
