  "print.colScore": "سکور",
  "plansLib.includes.recordPrints": "کاغذ تے ریکارڈ — ہفتہ وار شیڈول، تنخواہ رجسٹر، ٹائم شیٹ، تربیتی ریکارڈ، پالیسیاں تے شرائط، عملے دی فہرست تے قیمتاں دی فہرست، بھرے ہوئے چھپے یا ہتھ نال بھرن لئی خالی",
  "training.lessons.staff-record-prints.title": "کاغذ تے تواڈے ریکارڈ",
  "training.lessons.staff-record-prints.step1": "ایپ دے لگ بھگ ہر ریکارڈ دا ہن دستاویز اسٹائل اسٹوڈیو وچ کاغذی جڑواں اے: ہفتہ وار شیڈول، تنخواہ رجسٹر، ٹائم شیٹ، تربیتی ریکارڈ، تواڈی دکان دیاں پالیسیاں تے شرائط، عملے دی فہرست تے مصنوعات تے قیمتاں دی فہرست — تے Business پلان تے، سپلائر ڈائریکٹری تے بھریا ہویا درجہ حرارت لاگ۔ ہر اک تواڈے محفوظ دستاویزی انداز وچ، تواڈے کاروبار دی زبان وچ، تواڈیاں تاریخاں تواڈے انداز وچ لکھ کے چھپدا اے۔",
  "training.lessons.staff-record-prints.step2": "ہر کاغذ اوتھے ای ملدا اے جتھے اوس دا ریکارڈ رہندا اے۔ ورک فورس صفحے تے، شیڈول ٹیب ہفتہ اونہاں سب لئی چھاپدا اے جنہاں نوں تسیں دیکھ سکدے او، تے ٹائم کلاک ٹیب ٹائم شیٹ اوس دے اندراجات توں چھاپدا اے۔ چھپائی صرف اوہی دکھاؤندی اے جو تسیں اوس اسکرین تے پہلاں ای دیکھ سکدے او — چھپائی کدے کسے دی نظر وسیع نئیں کردی۔",
  "training.lessons.staff-record-prints.step3": "تنخواہ صفحے تے، تنخواہ دی مدت دا پیش منظر دیکھو تے رجسٹر چھاپو: ہر شخص، اوس دے گھنٹے، مجموعی، کٹوتیاں تے خالص اک شیٹ تے اجرت فائل لئی۔ تربیت صفحے تے، ٹیم سیکشن تربیتی ریکارڈ چھاپدا اے — کس نے کی مکمل کیتا، کوئز سکور تے تاریخاں نال۔",
  "training.lessons.staff-record-prints.step4": "تواڈی دکان دیاں پالیسیاں تے شرائط ترتیبات توں چھپدیاں نیں، بالکل اوسے طرح جیویں تسیں لکھیاں، نویں ملازم دے ہتھ یا دیوار لئی تیار۔ عملہ صفحہ اک صفحے دی فہرست چھاپدا اے، مصنوعات صفحہ قیمتاں دی فہرست چھاپدا اے، تے Business تے سپلائر صفحہ ڈائریکٹری تے درجہ حرارت لاگ صفحہ بھریا ہویا لاگ غذائی حفاظت فائل لئی چھاپدا اے۔",
  "training.lessons.staff-record-prints.step5": "ایس دے بجائے ہتھ نال بھرن والی شیٹ چاہیدی اے؟ پرنٹ سینٹر دے خالی فارماں وچ ہن اینہاں سارے کاغذات دا خالی جڑواں اے، دوواں پلاناں تے: اک چھاپو، قلم نال بھرو، تے چھپیاں نال فائل کرو۔",
  "ageCheck.title": "عمر دی جانچ",
  "ageCheck.intro": "ڈرائیونگ لائسنس یا شناختی کارڈ دے پچھلے پاسے والا بارکوڈ سکین کرو۔ توانوں اکو جواب ملدا اے — ہرا نشان یا لال نشان — تے ایپ سکین توں کجھ وی نہیں رکھدی: نہ نام، نہ نمبر، نہ جم تریخ، نہ کجھ لکھیا ہویا۔",
