  "settings.ageLines.title": "عمر دیاں حداں",
  "settings.ageLines.description": "اوہ عمر جس تک گاہک نوں ہر قسم دی ویچ لئی پہنچنا ضروری اے، تے سکین صفحے تے عمر دی جانچ اسے نوں ورتدی اے۔ ایہ حداں تواڈیاں نیں کہ تسی مقرر کرو — اوہناں نوں اس جگہ دے قانون مطابق رکھو جتھے تواڈا کاروبار اے۔ ایپ شراب لئی 21، تمباکو لئی 21، تے دوجے عمر دی پابندی والے سامان لئی 18 توں شروع ہوندی اے۔",
  "settings.ageLines.alcohol": "شراب — گھٹ توں گھٹ عمر",
