  "settings.ageLines.other": "دوجا عمر دی پابندی والا سامان — گھٹ توں گھٹ عمر",
  "plansLib.includes.ageCheck": "لائسنس سکین نال عمر دی جانچ — کسے کارڈ دا پچھلا پاسا سکین کرو تے ہرا یا لال نشان پاؤ، کارڈ توں کجھ وی نہیں رکھیا جاندا",
  "training.lessons.scanner-age-check.title": "لائسنس سکین نال عمر دی جانچ",
  "training.lessons.scanner-age-check.step1": "کجھ سامان صرف اوہناں گاہکاں نوں ویچیا جا سکدا اے جہڑے اک خاص عمر توں اتے ہون۔ سکین صفحے تے عمر دی جانچ کھولو، چنو کہ کی ویچیا جا رہیا اے — شراب، تمباکو یا دوجا عمر دی پابندی والا سامان — فیر گاہک دے ڈرائیونگ لائسنس یا شناختی کارڈ دے پچھلے بارکوڈ نوں سکین کرو۔",
  "training.lessons.scanner-age-check.step2": "جواب دو نشاناں وچوں اک اے۔ ہرا نشان دا مطلب اے گاہک دی عمر پوری اے تے ویچ اگے ودھ سکدی اے۔ لال نشان دا مطلب اے اوہ اس حد دی عمر تک نہیں پہنچیا، یا کارڈ دی مدت مک گئی اے — دوواں صورتاں وچ ویچ نہیں ہونی چاہیدی۔",
  "training.lessons.scanner-age-check.step3": "ایپ سکین توں کجھ وی نہیں رکھدی۔ کوئی نام، لائسنس نمبر یا جم تریخ کتھے وی محفوظ، بھیجی یا لکھی نہیں جاندی: جانچ اس اک سوال دا جواب دے کے مک جاندی اے۔ جانچے گئے کارڈاں دی کوئی فہرست نہیں جہنوں پچھے ویکھیا جا سکے — ایہ جان بجھ کے اے۔",
  "training.lessons.scanner-age-check.step4": "عمر دیاں حداں مالک دیاں نیں، جہڑا اوہناں نوں ترتیباں وچ اس جگہ دے قانون مطابق مقرر کردا اے جتھے کاروبار اے۔ ایہ جگہ جگہ تے ایپ دیاں شروع دیاں حداں توں وکھ ہو سکدیاں نیں، تے جانچ ہمیشہ اسی کاروبار لئی مالک دیاں حداں دی پیروی کردی اے جس وچ تسی ہو۔",
  "training.lessons.scanner-age-check.step5": "جے کوڈ نہ پڑھیا جاوے تے سکرین ایہ گل صاف کہندی اے۔ بارکوڈ صاف کر کے فیر کوشش کرو، یا کوئی ہور کارڈ منگو۔ جہڑا کوڈ شناختی کارڈ دا بارکوڈ نہیں، اوہنوں کدی ہرا نشان نہیں ملدا۔",
