  "plansLib.includes.ownTraining": "اپنی خود دی تربیت شامل کرو — اپنی ٹیم لئی اپنیاں تربیتاں اتے کوئز لکھو",
  "training.lessons.owner-own-training.title": "اپنی خود دی تربیت شامل کرنا",
  "training.lessons.owner-own-training.step1": "تربیت دے صفحے دے بالکل آخر وچ اپنی خود دی تربیت شامل کرو والا خانہ اے۔ اس نوں کھولو، نویں تربیت شروع کرو، اتے اس نوں عنوان دیو — تہاڈے حفاظتی اصول، تہاڈیاں احتیاطاں، تہاڈا کم کرن دا طریقہ۔",
  "training.lessons.owner-own-training.step2": "خود تربیت خانے وچ اپنے لفظاں وچ لکھو، یا اس دے بجائے اس نوں فائل دے طور تے اپ لوڈ کرو — PDF، متن، Word یا OpenDocument فائل۔ ٹائپ کیتے لفظ محفوظ فائل دی جگہ لے لیندے نیں، اتے فائل ٹائپ کیتے لفظاں دی جگہ لے لیندی اے۔",
  "training.lessons.owner-own-training.step3": "اس دے تھلے اس دا کوئز بناؤ: جتنے سوال چاہو، کثیر الانتخابی اتے تحریری جواب آزادانہ ملے ہوئے۔ تحریری سوال لئی او جواب لکھو جہڑا تسیں توقع کردے او؛ کثیر الانتخابی لئی درست والے تے نشان لاؤ۔",
  "training.lessons.owner-own-training.step4": "پاس لائن مقرر کرو، اتے چنو کہ تحریری جوابات کویں جانچے جان: تہاڈی جواب کنجی نال تقریباً لفظ بہ لفظ جانچے جان، یا تہاڈے کول بھیجے جان تاکہ تسیں پاس نشان زد کرو یا واپس بھیجو۔ فیر ٹھیک ٹھیک نشان لاؤ کہ ٹیم دے کون سے ارکان اے تربیت لیندے نیں — صرف اوہی اس نوں ویکھدے نیں۔",
  "training.lessons.owner-own-training.step5": "تسیں جہڑی وی تربیت محفوظ کردے او او خانے وچ اپنے سوالاں، لائن اتے نشانات دے نال الگ کھڑی رہندی اے، اتے تسیں جتنی چاہو شامل کر سکدے او۔ نتائج ہر تربیت دے تھلے خانے وچ آندے نیں؛ کوئی تربیت تدوں مکمل گنی جاندی اے جدوں سرور پاس کوشش دی جانچ کر لوے — یا، جانچ موڈ وچ، جدوں تسیں اس نوں پاس نشان زد کرو۔",
  "apiErrors.ownTrainingOwnerWrites": "اے تربیتاں صرف مالک لکھدا اے۔",
