  "apiErrors.ownTrainingTooLong": "او تربیت ایتھے ٹائپ کرن لئی بہت لمبی اے۔ تسیں اس دے بجائے اس نوں فائل دے طور تے اپ لوڈ کر سکدے او۔",
  "apiErrors.ownTrainingTicksList": "نشان زدہ لوکاں نوں فہرست دے طور تے بھیجو۔",
