  "print.pool.title": "بارکوڈ بناؤ",
  "print.pool.intro": "مصنوعات دے وجود وچ آن توں پہلاں بارکوڈ بناؤ۔ اوہناں نوں چھاپو، اوہناں ساماناں تے چپکاؤ جنہاں دا اپنا بارکوڈ نہیں، تے جدوں بعد وچ کوئی اک سکین ہووے، تے ایپ کوڈ نوں پچھان کے مصنوعات شامل کرن دی پیشکش کرے گی۔",
