  "print.pool.waiting": "توہاڈے پول وچ {count} غیر استعمال شدہ بارکوڈ انتظار کر رہے نیں۔",
  "print.pool.printNow": "ہنے چھاپو",
  "print.pool.savePdf": "PDF دے طور تے سانبھو",
  "print.pool.failed": "اوہ بارکوڈ نہیں بنائے جا سکے۔ مہربانی کرکے دوبارہ کوشش کرو۔",
  "scan.pool.title": "توہاڈے اپنے چھاپے ہوئے بارکوڈاں وچوں اک",
  "scan.pool.body": "ایہہ حالے توہاڈی دکان دی مصنوعات نہیں — ایہہ اوہ بارکوڈ اے جو تُسیں پہلاں ای چھاپیا سی۔ کیا تُسیں اینوں مصنوعات دے طور تے شامل کرنا چاہو گے؟",
  "plansLib.includes.barcodePool": "بارکوڈ پول — بارکوڈ پہلاں ای چھاپو، فیر ہر مصنوعات اوہدا بارکوڈ سکین ہون تے شامل کرو",
  "training.lessons.owner-barcode-pool.title": "مصنوعات توں پہلاں بارکوڈ چھاپنا",
  "training.lessons.owner-barcode-pool.step1": "کجھ ساماناں دا اپنا بارکوڈ نہیں ہوندا — ہتھ نال بنائیآں چیزاں، توہاڈے اپنے کتاباں والے تھیلے، جو کجھ وی تُسیں خود بناؤندے یا جوڑدے او۔ پرنٹ سیکشن وچ، بارکوڈ بناؤ دروازہ مصنوعات دے وجود وچ آن توں پہلاں کوڈ بناؤندا اے۔",
  "training.lessons.owner-barcode-pool.step2": "دسو کنے چاہیدے نیں — کوئی حد نہیں — تے ایپ توہاڈے کاروبار دے بارکوڈ پول وچ اونے ای نویں کوڈ ڈھالے گی۔ اوہ صرف توہاڈے کاروبار دے نیں، کدے دو وار نہیں دتے جاندے، تے اوہناں نوں بناؤن نال نہ مصنوعات بندی اے نہ سٹاک۔",
  "training.lessons.owner-barcode-pool.step3": "جس پل اوہ بن جان، چنو: ہنے لیبل دے طور تے چھاپو، یا بعد وچ چھاپن لئی PDF دے طور تے سانبھو۔ دوویں حالتاں وچ کوڈ پول وچ ای رہندے نیں، تے چھاپے لیبل پول نال بالکل میل کھاندے نیں۔",
  "training.lessons.owner-barcode-pool.step4": "ہر سامان بناؤندے ویلے اوہدے تے اک لیبل چپکاؤ۔ غیر استعمال شدہ کوڈ پول وچ صرف انتظار کردے نیں — کوئی کاہلی نہیں تے اوہ ختم نہیں ہوندے۔",
  "training.lessons.owner-barcode-pool.step5": "جدوں لیبل لگا سامان بعد وچ سکین ہووے، تے ایپ اپنا چھاپیا کوڈ پچھاندی اے تے کوڈ پہلاں ای بھریا ہویا مصنوعات شامل کرن دی پیشکش کردی اے۔ شامل ہون توں بعد، اوہ کوڈ اوس مصنوعات دا کوڈ بن جاندا اے تے کسے ہور وانگ سکین ہوندا اے۔",
