  "training.lessons.staff-checklists.title": "چیک لسٹ تے کم کرنا",
  "training.lessons.staff-checklists.step1": "چیک لسٹاں اوہ لسٹاں نیں جنہاں تے تہاڈا کاروبار چلدا اے — کھولنا، بند کرنا، صفائی، تے اوہ سبھ جو مالک طے کرے۔ ایہہ چیک لسٹاں وچ ملن گیاں: اج دیاں لسٹاں سبھ توں اتے، ٹک کرن لئی تیار۔",
  "training.lessons.staff-checklists.step2": "کسے چیز تے تد ہی ٹک کرو جدوں تسیں سچ مچ اوہ کر لیا ہووے۔ ہر ٹک لکھدا اے کہ کس نے کیتا تے کدوں، تاں جو اگلا شخص — تے گھر بیٹھا مالک — ویکھ سکے کہ کی ہو گیا تے کی باقی اے۔",
  "training.lessons.staff-checklists.step3": "کچھ چیزاں ٹک ہون توں پہلاں ثبوت منگدیاں نیں: پورے کم دی فوٹو، کسے کوڈ دا سکین، یا لکھیا درجہ حرارت۔ پہلاں ثبوت جوڑو، فیر ٹک کرو — اوہدے بغیر چیز ٹک نہیں ہووے گی۔",
  "training.lessons.staff-checklists.step4": "غلطی نال کچھ ٹک کر دتا؟ ٹک ہٹاؤ — پر صرف اپنے۔ مینیجر یا مالک کسے دی وی ٹک ہٹا سکدا اے، کیونکہ ٹک ناں والا اک ریکارڈ اے۔",
  "training.lessons.staff-checklists.step5": "چیک لسٹ تے کم کرن لئی تہانوں کدے اجازت نہیں چاہیدی۔ ٹیمپلیٹ بنانا تے ایہہ چننا کہ اوہ کس نوں سونپے جان، مالک دا کم اے، یا اوس شخص دا جس نوں مالک نے چیک لسٹ ٹیمپلیٹ دی ٹک دتی ہووے۔",
