  "training.lessons.staff-food-safety.step2": "حد سے باہر ریڈنگ اس وقت تک مکمل نہیں ہوتی جب تک اس کا نوٹ نہ کہے کہ آپ نے کیا کیا — دوبارہ ٹھنڈا کیا، دوبارہ گرم کیا، سینیٹائزر دوبارہ بنایا، پھینک دیا۔ نوٹ نہیں، محفوظ نہیں: اندراج قائم نہیں رہتا۔",
  "training.lessons.staff-food-safety.step3": "کولنگ، دوبارہ گرم کرنے اور سینیٹائزر چیکس کو درجہ حرارت کی طرح درج کریں: آپ نے کیا چیک کیا، ریڈنگ، اور چوکنے پر اصلاحی کارروائی۔",
  "training.lessons.staff-food-safety.step4": "سرٹیفکیٹ ختم ہونے سے پہلے وارننگ دیتے ہیں۔ جب آپ کا وارننگ دے، مالک کو بتائیں — اور کوئی بھی سیفٹی ڈیٹا شیٹس کو ان کی شیلف پر کسی بھی وقت پڑھ سکتا ہے۔",
  "training.lessons.staff-food-safety.step5": "معائنے سے پہلے — یا کسی بھی وقت — فوڈ سیفٹی شیلف سے فرضی معائنہ چلائیں اور انسپکٹر کی تاریخوں کے لیے معائنے کے لیے تیار پیکٹ چھاپیں۔",
